    33	export async function claimJob<TPayload>(queue: string, workerId: string, leaseSeconds = 60): Promise<ClaimedJob<TPayload> | undefined> {
    34	  return await transaction(async (client) => {
    35	    const result = await client.query<DurableJob<TPayload>>(
    36	      `UPDATE operations.jobs
    37	       SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
    38	           lease_expires_at=now()+($2 || ' seconds')::interval, last_error=NULL
    39	       WHERE id=(SELECT id FROM operations.jobs
    40	         WHERE queue=$3 AND status IN ('pending','retry') AND available_at<=now()
    41	         ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
    42	       RETURNING id,merchant_id,job_type,payload,attempts,max_attempts`,
    43	      [workerId, leaseSeconds, queue],
    44	    );
    45	    const job = result.rows[0];
    46	    if (!job) return undefined;
    47	    const attempt = await client.query<{ id: string }>(
    48	      `INSERT INTO operations.job_attempts(job_id,worker_id,status,started_at)
    49	       VALUES($1,$2,'processing',now()) RETURNING id`,
    50	      [job.id, workerId],
    51	    );
    52	    return { ...job, attemptId: attempt.rows[0]!.id };
    53	  });
    54	}
