  const subject = `PayFlow ${template.replaceAll('-', ' ')}`;
  const text = `${subject}\n\n${JSON.stringify(payload)}`;
  return { subject, text, html: `<h1>${subject}</h1><pre>${JSON.stringify(payload)}</pre>` };
}

